window.QB_TKP_B2 = [
{id:"TKP-091", q:"Seorang warga datang dengan surat kuasa untuk mengurus KTP ibunya yang sedang sakit. Surat kuasa hanya ditandatangani di atas materai tanpa cap RT/RW. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Menghubungi nomor kontak keluarga untuk verifikasi identitas, lalu memproses dengan catatan verifikasi", s:5},{t:"Meminta warga melengkapi pengesahan RT/RW atau membawa ibunya lain waktu", s:4},{t:"Menunda tanpa penjelasan sampai warga kembali dengan surat kuasa baru", s:3},{t:"Menerima surat kuasa apa adanya demi mempercepat pelayanan", s:2},{t:"Menolak mentah-mentah dan menyuruh warga pulang", s:1}], ex:"Verifikasi identitas mencegah penyalahgunaan data, sekaligus tidak mempersulit warga yang beriktikad baik."},
{id:"TKP-092", q:"Seorang ayah mengurus Kartu Identitas Anak (KIA) tetapi belum memiliki akta kelahiran anaknya. Ia mendesak karena KIA dibutuhkan untuk pendaftaran sekolah minggu depan. Sikap terbaik adalah ....", opts:[{t:"Menjelaskan alur pengurusan akta kelahiran dulu dan membantu memprosesnya berbarengan", s:5},{t:"Menyuruh warga kembali setelah akta kelahiran jadi tanpa penjelasan", s:4},{t:"Menolak dengan alasan aturan tidak bisa ditawar", s:3},{t:"Menerbitkan KIA tanpa akta kelahiran demi menolong warga", s:2},{t:"Meminta warga mencari calo agar cepat selesai", s:1}], ex:"Membantu warga menempuh jalur yang benar (akta dulu) adalah pelayanan tuntas, bukan jalan pintas yang melanggar aturan."},
{id:"TKP-093", q:"Seorang warga mengajukan surat keterangan usaha untuk pengajuan pinjaman bank, tetapi alamat usaha tidak sesuai domisili KTP. Keputusan Anda yang paling tepat adalah ....", opts:[{t:"Meminta bukti pendukung domisili usaha (misalnya surat keterangan RT/RW setempat) sebelum menerbitkan", s:5},{t:"Menolak dan melaporkan warga ke pihak berwajib sebagai penipu", s:4},{t:"Menerbitkan surat sesuai permintaan karena warga membutuhkan", s:3},{t:"Menerbitkan dengan alamat KTP saja tanpa verifikasi", s:2},{t:"Mengabaikan perbedaan alamat karena bukan urusan Anda", s:1}], ex:"Verifikasi domisili usaha melindungi keabsahan dokumen negara dan mencegah penyalahgunaan surat keterangan."},
{id:"TKP-094", q:"Anda melihat seorang warga berbadan sehat menggunakan jalur antrean prioritas (lansia/disabilitas) agar lebih cepat. Tindakan paling tepat adalah ....", opts:[{t:"Menghampiri dengan sopan, menjelaskan peruntukan jalur prioritas, dan mengarahkannya ke antrean umum", s:5},{t:"Menegur dengan suara keras di depan antrean lain agar jera", s:4},{t:"Memanggil satpam untuk mengusir warga tersebut", s:3},{t:"Membiarkan saja agar tidak ribut", s:2},{t:"Mencatat namanya dan mempersulit urusannya sebagai hukuman", s:1}], ex:"Penegakan aturan antrean prioritas paling efektif dengan teguran sopan dan edukasi, bukan hukuman atau pembiaran."},
{id:"TKP-095", q:"Kotak saran anonim di kantor Anda berisi laporan dugaan pungli oleh oknum petugas. Sebagai penanggung jawab, langkah terbaik adalah ....", opts:[{t:"Menindaklanjuti secara diam-diam: memeriksa pola laporan, CCTV, dan berkoordinasi dengan inspektorat", s:5},{t:"Mengumumkan ke seluruh pegawai bahwa ada laporan agar pelakunya takut", s:4},{t:"Mengabaikan karena laporan anonim tidak bisa dipertanggungjawabkan", s:3},{t:"Langsung menuduh petugas yang dicurigai di depan umum", s:2},{t:"Membuang surat itu agar nama unit tidak tercemar", s:1}], ex:"Laporan anonim tetap wajib ditindaklanjuti secara profesional dan rahasia melalui mekanisme pengawasan yang benar."},
{id:"TKP-096", q:"Mobil pelayanan keliling mogok di tengah jadwal kunjungan ke tiga desa. Warga sudah berkumpul menunggu. Keputusan Anda sebagai koordinator adalah ....", opts:[{t:"Menghubungi bengkel terdekat, memberitahu warga estimasi waktu, dan membuka layanan manual darurat untuk urusan sederhana", s:5},{t:"Menjadwalkan ulang tanpa pemberitahuan yang jelas", s:4},{t:"Menyuruh warga menunggu tanpa kepastian sampai mobil diperbaiki", s:3},{t:"Membatalkan seluruh jadwal dan pulang", s:2},{t:"Menyalahkan sopir di depan warga", s:1}], ex:"Komunikasi terbuka tentang kendala plus solusi darurat menunjukkan akuntabilitas pelayanan keliling."},
{id:"TKP-097", q:"Seorang warga meminta legalisasi ijazah, tetapi nama di ijazah berbeda satu huruf dengan di KTP. Ia bersikeras itu hanya salah ketik. Yang paling tepat Anda lakukan adalah ....", opts:[{t:"Menjelaskan bahwa perbedaan nama harus diperbaiki dulu lewat penetapan pengadilan, dan membantu menjelaskan alurnya", s:5},{t:"Menolak dan menyuruh warga mengurus ke pengadilan tanpa arahan", s:4},{t:"Melegalisasi saja karena perbedaannya sepele", s:3},{t:"Mengabaikan perbedaan dan tetap melegalisasi diam-diam", s:2},{t:"Meminta uang tambahan untuk 'membereskan' perbedaan nama", s:1}], ex:"Dokumen negara harus konsisten; mengarahkan warga ke penetapan pengadilan adalah solusi legal yang benar."},
{id:"TKP-098", q:"Seorang pemohon SKCK mengaku pernah dipidana ringan belasan tahun lalu dan sudah menjalani hukuman. Ia takut permohonannya ditolak. Sikap Anda yang paling tepat adalah ....", opts:[{t:"Memproses sesuai prosedur dan mencatat keterangan apa adanya; riwayat bukan otomatis alasan penolakan", s:5},{t:"Menolak permohonan karena ada riwayat pidana", s:4},{t:"Menerbitkan SKCK bersih tanpa mencatat riwayat demi kasihan", s:3},{t:"Menyuruh pemohon berbohong agar lolos verifikasi", s:2},{t:"Mempersulit prosesnya agar ia jera", s:1}], ex:"SKCK mencatat fakta hukum apa adanya; mantan narapidana yang sudah bebas berhak dilayani tanpa diskriminasi."},
{id:"TKP-099", q:"Seorang warga ingin mengurus pindah domisili, tetapi Kartu Keluarganya masih tercatat di daerah asal dan ia tidak bisa pulang. Solusi terbaik adalah ....", opts:[{t:"Mengarahkan warga mengurus surat keterangan pindah (SKPWNI) secara daring melalui Disdukcapil daerah asal", s:5},{t:"Menolak karena KK harus diurus di daerah asal", s:4},{t:"Menerbitkan domisili baru tanpa dasar dokumen", s:3},{t:"Memalsukan surat pindah dari daerah asal", s:2},{t:"Menyuruh warga menyewa calo di daerah asal", s:1}], ex:"Layanan administrasi kependudukan kini terhubung daring; mengarahkan ke SKPWNI online adalah solusi resmi tercepat."},
{id:"TKP-100", q:"Dua ahli waris ribut di loket Anda memperebutkan surat keterangan kematian orang tua mereka. Situasi memanas. Tindakan paling tepat adalah ....", opts:[{t:"Menenangkan keduanya, menjelaskan surat diterbitkan untuk keperluan administrasi (bukan penentu waris), dan menyarankan musyawarah atau jalur hukum untuk sengketa", s:5},{t:"Menolak menerbitkan surat sampai mereka damai", s:4},{t:"Mengusir keduanya dari kantor", s:3},{t:"Memihak ahli waris yang datang lebih dulu", s:2},{t:"Membiarkan mereka bertengkar agar kapok", s:1}], ex:"Petugas netral: surat kematian adalah dokumen administrasi, sengketa waris diselesaikan lewat musyawarah atau pengadilan."},
{id:"TKP-101", q:"Seorang warga tidak mampu meminta pembebasan biaya administrasi dan menunjukkan SKTM (Surat Keterangan Tidak Mampu) dari kelurahan. Namun atasan Anda berpesan 'jangan gampang kasih gratis'. Sikap Anda adalah ....", opts:[{t:"Memverifikasi keaslian SKTM, lalu memproses pembebasan sesuai ketentuan yang berlaku", s:5},{t:"Memberi gratis tanpa mencatat agar cepat", s:4},{t:"Meminta warga membayar separuh sebagai jalan tengah", s:3},{t:"Menyuruh warga kembali lain hari", s:2},{t:"Menolak sesuai pesan atasan", s:1}], ex:"SKTM yang valid adalah dasar hukum pembebasan biaya; pesan lisan atasan tidak boleh mengalahkan aturan tertulis."},
{id:"TKP-102", q:"Seorang ibu mengurus akta kelahiran anaknya; kolom nama ayah kosong karena anak lahir di luar nikah. Ia malu dan meminta Anda mengisinya dengan nama suaminya yang sekarang. Yang paling tepat adalah ....", opts:[{t:"Menjelaskan dengan empati bahwa akta mencatat fakta sebenarnya, kolom ayah boleh kosong, dan itu tidak mengurangi keabsahan akta", s:5},{t:"Menunda penerbitan sampai ada nama ayah", s:4},{t:"Menolak dengan kasar dan mempermalukannya", s:3},{t:"Mengisi nama suaminya demi menjaga perasaan ibu", s:2},{t:"Menyuruh ibu mencari orang yang mau mengaku sebagai ayah", s:1}], ex:"Akta kelahiran mencatat kebenaran; penjelasan empatik melindungi martabat ibu sekaligus keabsahan dokumen."},
{id:"TKP-103", q:"Jam pelayanan loket diubah lebih awal tanpa pemberitahuan, dan warga yang datang sesuai jadwal lama protes. Sebagai petugas yang bertugas, Anda sebaiknya ....", opts:[{t:"Meminta maaf atas kurangnya pemberitahuan, tetap melayani warga yang sudah datang, dan mengusulkan perbaikan pengumuman", s:5},{t:"Bersikeras mengikuti jadwal baru tanpa pengecualian", s:4},{t:"Menyalahkan pimpinan yang mengubah jadwal", s:3},{t:"Berpura-pura tidak tahu ada perubahan jadwal", s:2},{t:"Mengusir warga yang protes karena mengganggu", s:1}], ex:"Minta maaf, layani yang terdampak, dan perbaiki sistem pengumuman — itulah akuntabilitas pelayanan."},
{id:"TKP-104", q:"Pengaduan warga melalui kanal LAPOR! (SP4N) masuk ke unit Anda dengan tenggat tindak lanjut 10 hari kerja. Hari ke-9 Anda baru sempat membuka. Langkah terbaik adalah ....", opts:[{t:"Segera menindaklanjuti substansi pengaduan, memberi jawaban yang benar, dan mencatat evaluasi agar tidak terulang", s:5},{t:"Menjawab asal-asalan agar tenggat terpenuhi", s:4},{t:"Menyalahkan rekan yang seharusnya menangani", s:3},{t:"Membiarkan lewat tenggat karena sudah telat", s:2},{t:"Meminta admin menghapus pengaduan itu", s:1}], ex:"Keterlambatan bukan alasan mengabaikan; selesaikan dengan benar dan perbaiki manajemen pengaduan ke depan."},
{id:"TKP-105", q:"Seorang warga tunanetra datang dengan pendamping yang mengaku kerabat. Anda curiga pendamping memanfaatkan situasi. Tindakan paling tepat adalah ....", opts:[{t:"Berkomunikasi langsung dengan warga tunanetra untuk memastikan kehendak dan pemahamannya, serta mencatat identitas pendamping", s:5},{t:"Mengusir pendamping karena mencurigakan", s:4},{t:"Membiarkan saja karena bukan urusan Anda", s:3},{t:"Menolak melayani keduanya", s:2},{t:"Melaporkan keduanya ke polisi tanpa bukti", s:1}], ex:"Pastikan kehendak warga difabel secara langsung; catat identitas pendamping sebagai perlindungan, bukan tuduhan."},
{id:"TKP-106", q:"Seorang warga kehilangan surat pengantar RT/RW dan diminta petugas lain bolak-balik mengurusnya lagi. Ia sudah kelelahan dan emosi di loket Anda. Sikap terbaik adalah ....", opts:[{t:"Membantu memverifikasi data melalui sistem/ar sip yang ada agar warga tidak bolak-balik, sambil menjelaskan", s:5},{t:"Mengirimnya kembali ke RT/RW sesuai prosedur", s:4},{t:"Menyuruhnya datang besok saja", s:3},{t:"Memarahinya karena tidak menjaga dokumen", s:2},{t:"Membuatkan surat pengantar palsu agar cepat", s:1}], ex:"Memanfaatkan data yang sudah ada di sistem untuk membantu warga adalah pelayanan efisien tanpa mengorbankan tertib administrasi."},
{id:"TKP-107", q:"Seorang lansia pikun sudah tiga kali datang ke loket Anda minggu ini karena lupa membawa berkas yang diminta. Tindakan paling tepat adalah ....", opts:[{t:"Menuliskan daftar berkas dengan huruf besar dan jelas, memintanya menunjukkan catatan itu saat datang, serta menawarkan menghubungi keluarganya", s:5},{t:"Membiarkan ia terus datang tanpa bantuan", s:4},{t:"Menolak melayaninya karena merepotkan", s:3},{t:"Menertawakannya bersama rekan", s:2},{t:"Menyuruh satpam melarangnya masuk lagi", s:1}], ex:"Bantuan konkret (catatan jelas + libatkan keluarga) menyelesaikan akar masalah warga lansia yang pelupa."},
{id:"TKP-108", q:"Seorang warga mengurus surat keterangan domisili usaha (untuk NIB), tetapi lokasi usahanya berada di zona hijau yang dilarang untuk kegiatan usaha. Keputusan Anda adalah ....", opts:[{t:"Menolak dengan penjelasan bahwa lokasi melanggar tata ruang, dan menyarankan alternatif lokasi atau jenis usaha yang sesuai", s:5},{t:"Menerbitkan surat demi membantu perekonomian warga", s:4},{t:"Mengabaikan aturan zonasi karena bukan wewenang loket", s:3},{t:"Menerbitkan diam-diam tanpa mencatat", s:2},{t:"Meminta bayaran tambahan untuk meloloskan", s:1}], ex:"Menolak dengan solusi alternatif menegakkan tata ruang sekaligus tetap membantu warga mencari jalan legal."},
{id:"TKP-109", q:"Seorang ibu membawa anak berkebutuhan khusus (autis) yang gelisah karena ruang tunggu bising dan penuh. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Menyediakan ruang tunggu yang lebih tenang atau memprioritaskan pelayanan dengan persetujuan antrean lain", s:5},{t:"Meminta ibu menunggu di luar sampai giliran dipanggil", s:4},{t:"Menyuruh ibu pulang dan kembali saat sepi", s:3},{t:"Mengabaikan karena semua warga antre sama", s:2},{t:"Menegur ibu karena anaknya mengganggu", s:1}], ex:"Akomodasi yang wajar bagi warga berkebutuhan khusus adalah wujud pelayanan inklusif."},
{id:"TKP-110", q:"Anda menemukan dompet berisi uang dan KTP milik warga tertinggal di meja loket setelah jam pelayanan selesai. Tindakan paling tepat adalah ....", opts:[{t:"Mencatat temuan, menyerahkannya ke bagian keamanan/umum sesuai prosedur barang temuan, dan mencoba menghubungi pemilik via data KTP", s:5},{t:"Menyimpan dompet di laci pribadi dan menunggu ada yang mencari", s:4},{t:"Membuang dompet agar tidak merepotkan", s:3},{t:"Mengambil uangnya sebagai 'upah' karena sudah lembur", s:2},{t:"Membagikan uangnya ke rekan-rekan", s:1}], ex:"Barang temuan wajib dicatat dan diserahkan lewat prosedur resmi; menghubungi pemilik adalah bentuk integritas."},
{id:"TKP-111", q:"Seorang warga pekerja shift malam meminta dilayani di luar jam kerja karena ia tidak bisa datang pagi. Kebijakan kantor tidak mengenal layanan di luar jam. Sikap Anda adalah ....", opts:[{t:"Menjelaskan keterbatasan jam layanan, menawarkan layanan daring atau surat kuasa, dan meneruskan usulan jam layanan fleksibel ke pimpinan", s:5},{t:"Menolak mentah-mentah sesuai aturan", s:4},{t:"Melayani diam-diam di luar jam tanpa izin", s:3},{t:"Mengabaikan permintaannya", s:2},{t:"Memintanya bolos kerja saja", s:1}], ex:"Memberi alternatif resmi (daring/kuasa) plus meneruskan aspirasi ke pimpinan menyeimbangkan aturan dan kebutuhan warga."},
{id:"TKP-112", q:"Dua warga berebut nomor antrean yang jatuh di lantai; keduanya mengklaim nomor kecil itu miliknya dan hampir baku hantam. Tindakan Anda adalah ....", opts:[{t:"Melerai dengan tenang, memeriksa sistem nomor antrean elektronik, dan memberi nomor pengganti yang adil", s:5},{t:"Memihak yang terlihat lebih tua", s:4},{t:"Mengusir keduanya dari antrean", s:3},{t:"Membiarkan mereka menyelesaikan sendiri", s:2},{t:"Memanggil polisi untuk hal sepele ini", s:1}], ex:"Verifikasi data antrean menyelesaikan sengketa secara objektif tanpa memihak."},
{id:"TKP-113", q:"Seorang warga yang kecewa mengancam akan memviralkan dan melaporkan Anda ke wali kota karena permohonannya ditolak sesuai aturan. Respons terbaik adalah ....", opts:[{t:"Tetap tenang, menjelaskan dasar penolakan dengan sopan, memberitahu hak warga untuk mengajukan keberatan resmi, dan mendokumentasikan kejadian", s:5},{t:"Kabur dari loket menghindari konfrontasi", s:4},{t:"Mengabulkan permohonannya karena takut viral", s:3},{t:"Balik mengancam warga tersebut", s:2},{t:"Menyuapnya agar tidak melapor", s:1}], ex:"Keputusan berbasis aturan tidak goyah oleh ancaman; hak keberatan resmi adalah saluran yang benar bagi warga."},
{id:"TKP-114", q:"Seorang warga lanjut usia menelepon karena tidak paham cara mengunggah berkas ke layanan daring. Ia meminta dipandu lewat telepon. Yang paling tepat adalah ....", opts:[{t:"Memandu langkah demi langkah dengan sabar tanpa meminta data rahasia, atau menawarkan datang dengan pendamping keluarga", s:5},{t:"Menyuruhnya datang langsung saja", s:4},{t:"Menyuruhnya minta tolong tetangga saja", s:3},{t:"Menutup telepon karena bukan tugas loket", s:2},{t:"Meminta kata sandi akunnya agar Anda yang mengerjakan", s:1}], ex:"Panduan sabar tanpa meminta kredensial melindungi keamanan data sekaligus membantu warga gaptek."},
{id:"TKP-115", q:"Seorang warga mengajukan surat keterangan belum menikah untuk syarat CPNS, padahal dari data Anda ia menikah siri setahun lalu. Tindakan Anda adalah ....", opts:[{t:"Menolak menerbitkan keterangan yang tidak benar, menjelaskan risikonya, dan menyarankan mengurus pencatatan nikah terlebih dahulu", s:5},{t:"Menolak dan mengancam melaporkannya sebagai penipu", s:4},{t:"Menerbitkan surat karena nikah siri tidak tercatat resmi", s:3},{t:"Menerbitkan diam-diam demi kasihan", s:2},{t:"Meminta bayaran untuk menutup mata", s:1}], ex:"Surat keterangan harus berisi kebenaran; mengarahkan ke pencatatan nikah memberi jalan keluar yang sah."},
{id:"TKP-116", q:"Seorang rekanan rutin memberi parsel lebaran kepada seluruh pegawai, termasuk Anda. Nilainya wajar tetapi ia sedang mengikuti tender di unit Anda. Sikap terbaik adalah ....", opts:[{t:"Menolak dan melaporkan ke atasan/UPG karena ada konflik kepentingan tender", s:5},{t:"Menerima lalu membagikan ke warga miskin", s:4},{t:"Menolak dengan kasar di depan rekanan", s:3},{t:"Menerima karena nilainya kecil dan merata", s:2},{t:"Menerima diam-diam agar tidak menyinggung", s:1}], ex:"Gratifikasi dari pihak yang berkepentingan wajib ditolak dan dilaporkan, berapa pun nilainya."},
{id:"TKP-117", q:"Dalam perjalanan dinas luar kota, panitia mengajak rombongan mampir ke tempat wisata dengan biaya panitia. Sikap Anda yang paling tepat adalah ....", opts:[{t:"Menolak dengan halus dan tetap fokus pada agenda dinas", s:5},{t:"Ikut saja karena sudah dibayar panitia", s:4},{t:"Ikut tetapi pura-pura tidak tahu itu wisata", s:3},{t:"Mengajak panitia ke wisata yang lebih jauh", s:2},{t:"Ikut lalu meminta kuitansi wisata untuk diklaim", s:1}], ex:"Menolak ajakan di luar agenda dinas menjaga integritas penggunaan waktu dan anggaran negara."},
{id:"TKP-118", q:"Setelah kegiatan selesai ada sisa uang saku panitia. Ketua panitia mengusulkan dibagi rata sebagai 'uang lelah'. Tindakan Anda adalah ....", opts:[{t:"Menolak dan mengusulkan sisa dikembalikan ke kas negara sesuai ketentuan", s:5},{t:"Menolak tetapi membiarkan yang lain membagi", s:4},{t:"Mengusulkan dibelikan makanan untuk panitia", s:3},{t:"Setuju karena semua sudah bekerja keras", s:2},{t:"Menerima bagian Anda lalu diam", s:1}], ex:"Sisa anggaran adalah uang negara; pengembaliannya wajib mengikuti ketentuan, bukan dibagi-bagi."},
{id:"TKP-119", q:"Atasan menitipkan nama keponakannya agar diterima magang di unit Anda, padahal kuota magang sudah penuh. Sikap terbaik adalah ....", opts:[{t:"Menjelaskan kuota sudah penuh dan mekanisme seleksi magang, serta menawarkan alternatif unit lain yang masih membuka", s:5},{t:"Menolak secara terbuka di depan banyak orang", s:4},{t:"Mengabaikan titipan itu", s:3},{t:"Menerima demi menjaga hubungan dengan atasan", s:2},{t:"Menerima lalu menggeser peserta magang lain", s:1}], ex:"Menjelaskan mekanisme dan menawarkan alternatif menolak nepotisme tanpa merusak hubungan kerja."},
{id:"TKP-120", q:"Anda melihat rekan rutin memakai mobil dinas untuk keperluan pribadi setiap akhir pekan. Tindakan paling tepat adalah ....", opts:[{t:"Mengingatkan rekan secara pribadi bahwa itu pelanggaran, dan bila berlanjut melapor ke atasan/pengelola aset", s:5},{t:"Melaporkan langsung ke polisi", s:4},{t:"Memfoto dan memviralkan di media sosial", s:3},{t:"Membiarkan karena bukan urusan Anda", s:2},{t:"Ikut meminjam mobil dinas juga", s:1}], ex:"Teguran pribadi dulu, lalu jalur resmi bila berlanjut — proporsional dan menjaga martabat rekan."},
{id:"TKP-121", q:"Anda diminta menandatangani berita acara serah terima yang tanggalnya dimundurkan dua minggu agar cocok dengan SPJ. Tindakan Anda adalah ....", opts:[{t:"Menolak menandatangani dokumen yang tidak sesuai fakta dan meminta tanggal yang benar", s:5},{t:"Menandatangani lalu melapor diam-diam", s:4},{t:"Menandatangani karena hanya soal tanggal", s:3},{t:"Menyuruh rekan lain yang menandatangani", s:2},{t:"Meminta imbalan untuk tanda tangan", s:1}], ex:"Menandatangani dokumen backdate adalah pemalsuan; menolak dengan meminta fakta yang benar melindungi Anda secara hukum."},
{id:"TKP-122", q:"Menjelang pemeriksaan BPK, atasan meminta Anda 'membereskan' dokumen pendukung yang sebenarnya tidak ada. Sikap terbaik adalah ....", opts:[{t:"Menolak membuat dokumen fiktif dan menyampaikan kondisi apa adanya, serta mengusulkan perbaikan ke depan", s:5},{t:"Mengundurkan diri seketika", s:4},{t:"Menyalahkan bagian lain atas hilangnya dokumen", s:3},{t:"Membantu membuatkan tetapi tidak menandatangani", s:2},{t:"Membuatkan dokumen pendukung palsu", s:1}], ex:"Membuat dokumen fiktif untuk audit adalah pelanggaran pidana; kejujuran plus rencana perbaikan adalah jalan yang benar."},
{id:"TKP-123", q:"Seorang rekan menawarkan jasa 'mengurus' kenaikan jabatan eselon dengan imbalan sejumlah uang (calo jabatan). Respons Anda adalah ....", opts:[{t:"Menolak tawaran dan melaporkan praktik percaloan itu ke atasan/aparat pengawas", s:5},{t:"Menolak tetapi merahasiakannya", s:4},{t:"Menyebarkan tawaran itu ke rekan lain", s:3},{t:"Menerima tawaran karena ingin naik jabatan cepat", s:2},{t:"Meminta potongan harga dulu", s:1}], ex:"Jual beli jabatan adalah korupsi; menolak saja tidak cukup — praktiknya wajib dilaporkan."},
{id:"TKP-124", q:"Dalam SPJ kegiatan, tercantum honorarium narasumber yang sebenarnya tidak pernah hadir. Bendahara meminta Anda ikut menandatangani. Tindakan Anda adalah ....", opts:[{t:"Menolak menandatangani dan meminta daftar honorarium diperbaiki sesuai fakta", s:5},{t:"Diam saja dan tidak menandatangani tanpa penjelasan", s:4},{t:"Menandatangani dengan catatan kecil", s:3},{t:"Menandatangani karena semua sudah biasa begitu", s:2},{t:"Meminta bagian honorarium fiktif itu", s:1}], ex:"Honorarium fiktif adalah penggelapan; menolak dan meminta perbaikan SPJ sesuai fakta adalah kewajiban."},
{id:"TKP-125", q:"Atasan meminta Anda merahasiakan temuannya tentang pelanggaran dari tim inspektorat yang akan datang. Sikap Anda adalah ....", opts:[{t:"Menolak menutupi dan bersikap kooperatif dengan inspektorat sesuai fakta", s:5},{t:"Menuruti tetapi diam-diam memberi tahu inspektorat", s:4},{t:"Membocorkan ke media agar ramai", s:3},{t:"Berpura-pura tidak tahu apa-apa", s:2},{t:"Menuruti atasan demi loyalitas", s:1}], ex:"Loyalitas kepada atasan tidak boleh mengalahkan kewajiban hukum; kooperatif dengan pengawas adalah sikap benar."},
{id:"TKP-126", q:"Anda ditunjuk sebagai PPK dalam tender yang diikuti perusahaan milik teman kuliah Anda. Sikap paling tepat adalah ....", opts:[{t:"Mengundurkan diri dari jabatan PPK/menyatakan konflik kepentingan dan meminta digantikan", s:5},{t:"Meminta teman mengundurkan diri dari tender", s:4},{t:"Tetap menjabat tetapi bersikap objektif", s:3},{t:"Merahasiakan hubungan pertemanan itu", s:2},{t:"Tetap menjabat dan memastikan teman Anda menang", s:1}], ex:"Konflik kepentingan wajib dinyatakan dan dihindari dengan mundur dari posisi pengambil keputusan."},
{id:"TKP-127", q:"Seorang rekan meminta Anda memberinya nilai SKP sangat baik, padahal kinerjanya biasa saja. Ia beralasan 'saling bantu'. Respons Anda adalah ....", opts:[{t:"Menilai secara objektif sesuai bukti kinerja yang ada", s:5},{t:"Menolak dengan memakinya", s:4},{t:"Memberi nilai rendah sebagai hukuman", s:3},{t:"Memberi nilai tinggi demi menjaga pertemanan", s:2},{t:"Memberi nilai tinggi dengan syarat ia juga menilai Anda tinggi", s:1}], ex:"Penilaian kinerja harus berbasis bukti; nilai yang diobral merusak meritokrasi."},
{id:"TKP-128", q:"Anda diminta 'memotong' dana bantuan untuk operasional kantor dengan alasan anggaran operasional kurang. Tindakan Anda adalah ....", opts:[{t:"Menolak karena dana bantuan harus utuh sampai ke penerima yang berhak", s:5},{t:"Menolak tetapi tidak melapor", s:4},{t:"Mengusulkan potongan yang lebih kecil", s:3},{t:"Setuju karena untuk kepentingan kantor juga", s:2},{t:"Setuju asalkan tidak ketahuan", s:1}], ex:"Dana bantuan adalah hak penerima; pemotongan dengan alasan apa pun adalah penyalahgunaan."},
{id:"TKP-129", q:"Seorang rekanan menawarkan Anda posisi komisaris di BUMD mitranya dengan honor besar, tanpa mengganggu jam kerja. Sikap terbaik adalah ....", opts:[{t:"Menolak karena berpotensi konflik kepentingan dan wajib izin tertulis atasan sesuai aturan", s:5},{t:"Menolak dengan kasar", s:4},{t:"Menerima karena tidak mengganggu pekerjaan", s:3},{t:"Menerima diam-diam", s:2},{t:"Menerima lalu mengatur proyek ke BUMD itu", s:1}], ex:"Rangkap jabatan oleh ASN diatur ketat dan berpotensi konflik kepentingan; tolak dan patuhi aturan."},
{id:"TKP-130", q:"Rekan Anda membuat surat tugas fiktif agar bisa mengklaim uang perjalanan dinas. Ia mengajak Anda ikut serta. Respons Anda adalah ....", opts:[{t:"Menolak ikut dan mengingatkan rekan bahwa itu penggelapan; bila berlanjut, laporkan", s:5},{t:"Membiarkan tanpa peduli", s:4},{t:"Ikut sekali saja", s:3},{t:"Ikut karena lumayan untuk tambahan", s:2},{t:"Tidak ikut tetapi membantu membuatkan suratnya", s:1}], ex:"Klaim perjalanan dinas fiktif adalah korupsi; menolak plus mengingatkan adalah batas minimal, laporkan bila berlanjut."},
{id:"TKP-131", q:"Seorang rekan menyimpan proyektor dan laptop dinas di rumahnya 'agar aman'. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Mengingatkannya bahwa aset dinas wajib tercatat dan disimpan di kantor, serta menyarankan mengembalikan", s:5},{t:"Melaporkan langsung ke polisi", s:4},{t:"Membiarkan karena niatnya baik", s:3},{t:"Menyebarkan ke grup kantor agar malu", s:2},{t:"Ikut meminjam untuk di rumah", s:1}], ex:"Aset negara wajib tercatat dan berada di tempat resmi; penguasaan pribadi adalah penyalahgunaan."},
{id:"TKP-132", q:"Atasan meminta Anda menghapus riwayat chat yang berisi perintahnya yang bermasalah. Sikap Anda adalah ....", opts:[{t:"Menolak menghapus dan menyimpan bukti sesuai kebutuhan, serta tidak ikut menutupi", s:5},{t:"Menghapus tetapi menyimpan salinannya untuk berjaga", s:4},{t:"Menyebarkan chat itu ke grup", s:3},{t:"Menghapus demi loyalitas atasan", s:2},{t:"Menghapus dan meminta imbalan", s:1}], ex:"Menghapus bukti adalah perintangan; menolak dengan tetap menyimpan fakta melindungi Anda dan kebenaran."},
{id:"TKP-133", q:"Di unit Anda ada pungutan 'uang kas' rutin antarpegawai yang penggunaannya tidak pernah dilaporkan transparan. Sikap terbaik adalah ....", opts:[{t:"Menolak membayar dan mengusulkan pengelolaan kas yang transparan dan tercatat", s:5},{t:"Melaporkan sebagai pungli ke polisi seketika", s:4},{t:"Ikut membayar agar tidak dikucilkan", s:3},{t:"Membayar tetapi mengomel di belakang", s:2},{t:"Menghasut rekan lain untuk tidak membayar", s:1}], ex:"Iuran sukarela harus transparan; mengusulkan pencatatan terbuka menyelesaikan masalah tanpa konflik."},
{id:"TKP-134", q:"Anda melihat rekan menerima amplop dari seorang warga di area parkir kantor. Tindakan paling tepat adalah ....", opts:[{t:"Menegur rekan secara pribadi dan mengingatkan risiko gratifikasi; bila terindikasi suap, laporkan ke kanal resmi", s:5},{t:"Langsung melapor ke KPK tanpa konfirmasi", s:4},{t:"Memfoto dan langsung memviralkan", s:3},{t:"Mengabaikan karena tidak melihat isinya", s:2},{t:"Meminta bagian dari amplop itu", s:1}], ex:"Konfirmasi dan teguran proporsional dulu; pelaporan resmi menyusul bila ada indikasi pelanggaran."},
{id:"TKP-135", q:"Seorang 'orang dalam' meminta Anda meloloskan berkas perizinan yang tidak lengkap milik kenalannya. Tindakan Anda adalah ....", opts:[{t:"Menolak dengan tegas dan memproses berkas sesuai kelengkapan yang dipersyaratkan", s:5},{t:"Melempar berkas ke rekan lain", s:4},{t:"Meloloskan separuh saja", s:3},{t:"Meloloskan demi menjaga relasi", s:2},{t:"Meminta imbalan atas kelonggaran itu", s:1}], ex:"Kelengkapan berkas adalah syarat mutlak; intervensi orang dalam tidak boleh mengubah keputusan."},
{id:"TKP-136", q:"Tim Anda gagal mencapai target kinerja dan para anggota saling menyalahkan di grup chat. Sebagai anggota tim, sikap terbaik adalah ....", opts:[{t:"Mengajak tim evaluasi objektif: mengakui bagian kesalahan masing-masing dan menyusun rencana perbaikan bersama", s:5},{t:"Diam saja menunggu masalah reda", s:4},{t:"Keluar dari grup agar tidak terlibat", s:3},{t:"Menyalahkan pimpinan yang memberi target terlalu tinggi", s:2},{t:"Ikut menyalahkan anggota yang paling lemah", s:1}], ex:"Evaluasi jujur dan rencana perbaikan bersama mengubah kegagalan menjadi pembelajaran tim."},
{id:"TKP-137", q:"Perwakilan dinas lain tidak hadir dalam rapat koordinasi penting padahal kehadirannya krusial. Tindakan Anda sebagai peserta adalah ....", opts:[{t:"Menghubungi perwakilan tersebut, menanyakan kendala, dan menyepakati tindak lanjut tertulis agar koordinasi tetap jalan", s:5},{t:"Melanjutkan rapat dan mengambil keputusan sepihak", s:4},{t:"Membatalkan rapat dan menyalahkan dinas itu", s:3},{t:"Melaporkan ke gubernurnya", s:2},{t:"Mengabaikan dan menganggap dinas itu tidak penting", s:1}], ex:"Komunikasi proaktif mencari solusi menjaga koordinasi lintas dinas tetap berjalan."},
{id:"TKP-138", q:"Anda yang relatif junior diminta memimpin tim yang anggotanya lebih senior dan berpengalaman. Sikap terbaik adalah ....", opts:[{t:"Menerima dengan rendah hati, memanfaatkan pengalaman para senior, membagi peran jelas, dan memutuskan dengan musyawarah", s:5},{t:"Menyerahkan semua keputusan ke yang paling senior", s:4},{t:"Menolak karena merasa tidak pantas", s:3},{t:"Membiarkan tim berjalan sendiri", s:2},{t:"Memerintah dengan otoriter agar dihormati", s:1}], ex:"Kepemimpinan yang merangkul pengalaman senior dan musyawarah membangun kewibawaan, bukan otoriter."},
{id:"TKP-139", q:"Anda pekerja sistematis, sedangkan rekan satu tim spontan dan tenggat tinggal dua hari. Cara terbaik menyikapinya adalah ....", opts:[{t:"Membagi tugas sesuai kekuatan masing-masing dan menyepakati titik cek harian agar tetap sinkron", s:5},{t:"Mengerjakan semuanya sendiri agar rapi", s:4},{t:"Menyerah dan pasrah pada hasil", s:3},{t:"Memaksa rekan mengikuti cara Anda", s:2},{t:"Mengeluh ke atasan tentang gaya rekan", s:1}], ex:"Memanfaatkan perbedaan gaya kerja lewat pembagian peran dan cek rutin adalah kolaborasi dewasa."},
{id:"TKP-140", q:"Dua rekan satu tim Anda tidak akur dan konfliknya menghambat pekerjaan. Anda diminta menjadi penengah. Tindakan terbaik adalah ....", opts:[{t:"Mempertemukan keduanya secara netral, mendengarkan masing-masing, dan memfokuskan pada tujuan bersama pekerjaan", s:5},{t:"Menyuruh salah satunya pindah tim", s:4},{t:"Melaporkan keduanya ke atasan agar dihukum", s:3},{t:"Membiarkan mereka berkonflik sampai lelah", s:2},{t:"Memihak rekan yang lebih dekat dengan Anda", s:1}], ex:"Mediasi netral yang mengembalikan fokus ke tujuan pekerjaan menyelesaikan konflik secara dewasa."},
{id:"TKP-141", q:"Anda dan unit lain mengerjakan tugas bersama tanpa SK resmi sehingga tidak jelas siapa penanggung jawab. Sikap terbaik adalah ....", opts:[{t:"Mengusulkan pembagian peran tertulis dan disepakati kedua pimpinan agar akuntabel", s:5},{t:"Mengambil alih semuanya sendiri", s:4},{t:"Menolak terlibat karena tidak ada SK", s:3},{t:"Mengerjakan seadanya sambil menunggu kejelasan", s:2},{t:"Saling lempar tanggung jawab dengan unit lain", s:1}], ex:"Mengusulkan pembagian peran tertulis menciptakan akuntabilitas meski SK formal belum ada."},
{id:"TKP-142", q:"Seorang rekan mengambil cuti mendadak tepat saat proyek kritis berjalan. Beban kerjanya jatuh ke Anda. Tindakan paling tepat adalah ....", opts:[{t:"Mengambil alih tugas kritisnya, mendokumentasikan serah terima singkat, dan membahas pembagian ulang dengan atasan", s:5},{t:"Menolak mengerjakan tugasnya", s:4},{t:"Mengancam akan melaporkannya", s:3},{t:"Mengerjakan sambil mengomel dan menyebarkan kebencian", s:2},{t:"Membiarkan tugasnya terbengkalai", s:1}], ex:"Mengamankan pekerjaan kritis dulu, lalu menata ulang pembagian tugas lewat atasan adalah profesional."},
{id:"TKP-143", q:"Hasil evaluasi kinerja tim Anda buruk dan pimpinan meminta Anda menyampaikannya ke tim. Cara terbaik adalah ....", opts:[{t:"Menyampaikan fakta secara terbuka, mengajak tim menganalisis penyebab, dan menyusun perbaikan bersama", s:5},{t:"Menyampaikan lewat grup chat tanpa diskusi", s:4},{t:"Menyampaikan dengan nada menyalahkan agar tim takut", s:3},{t:"Menyembunyikan hasil buruk agar tim tidak down", s:2},{t:"Melempar kesalahan ke tim lain", s:1}], ex:"Keterbukaan fakta plus ajakan perbaikan bersama membangun akuntabilitas tim, bukan ketakutan."},
{id:"TKP-144", q:"Unit Anda berkolaborasi dengan perusahaan swasta (program CSR) yang budaya kerjanya serba cepat dan informal, berbeda dengan birokrasi. Sikap terbaik adalah ....", opts:[{t:"Menyepakati pola kerja bersama di awal: target, alur persetujuan, dan komunikasi rutin agar kedua budaya bertemu", s:5},{t:"Memaksa pihak swasta mengikuti seluruh prosedur birokrasi", s:4},{t:"Membiarkan berjalan tanpa kesepakatan", s:3},{t:"Mengabaikan aturan demi kecepatan mitra", s:2},{t:"Menolak kerja sama karena tidak cocok", s:1}], ex:"Kesepakatan kerja bersama di awal menjembatani perbedaan budaya birokrasi dan swasta."},
{id:"TKP-145", q:"Rekan yang dimutasi mendadak tidak sempat serah terima tugas kepada Anda sebagai penggantinya. Tindakan terbaik adalah ....", opts:[{t:"Menghubungi rekan tersebut untuk penjelasan, menelusuri dokumen yang ada, dan membuat catatan serah terima susulan", s:5},{t:"Menunggu rekan kembali untuk serah terima", s:4},{t:"Mengerjakan berdasarkan tebakan sendiri", s:3},{t:"Menolak tugas karena tidak ada serah terima", s:2},{t:"Menyalahkan rekan yang mutasi", s:1}], ex:"Proaktif menghubungi dan menelusuri dokumen memastikan kesinambungan tugas meski serah terima formal terlewat."},
{id:"TKP-146", q:"Dalam rapat daring, sebagian peserta mematikan kamera dan jelas tidak menyimak. Sebagai moderator, Anda sebaiknya ....", opts:[{t:"Membuat rapat interaktif (tanya jawab bergiliran), membatasi durasi, dan membagikan notulen keputusan", s:5},{t:"Mematikan rapat dan mengulang lain waktu", s:4},{t:"Membiarkan karena rapat daring memang begitu", s:3},{t:"Memarahi peserta yang tidak menyimak", s:2},{t:"Mengeluarkan peserta dari rapat", s:1}], ex:"Rapat daring yang interaktif dan ringkas menjaga partisipasi tanpa perlu paksaan."},
{id:"TKP-147", q:"Ide Anda ditolak mentah-mentah dalam forum rapat tanpa diberi alasan. Respons paling tepat adalah ....", opts:[{t:"Menanyakan alasan penolakan dengan tenang, meminta masukan perbaikan, dan menyempurnakan usulan", s:5},{t:"Tersinggung dan tidak mau bicara lagi", s:4},{t:"Menarik ide dan tidak pernah mengusul lagi", s:3},{t:"Memaksa forum menerima ide Anda", s:2},{t:"Menjelekkan forum di belakang", s:1}], ex:"Meminta alasan dan masukan mengubah penolakan menjadi kesempatan menyempurnakan gagasan."},
{id:"TKP-148", q:"Tim dadakan dibentuk untuk persiapan kunjungan menteri besok pagi. Waktu sangat sempit dan peran belum jelas. Sikap Anda adalah ....", opts:[{t:"Segera berkoordinasi, mengambil peran sesuai kemampuan, dan memastikan hal-hal kritis tertangani", s:5},{t:"Menunggu perintah rinci sebelum bergerak", s:4},{t:"Mengerjakan sendiri tanpa koordinasi", s:3},{t:"Mengeluh tentang persiapan mendadak", s:2},{t:"Berpura-pura sibuk agar tidak kebagian tugas", s:1}], ex:"Inisiatif mengambil peran dan koordinasi cepat adalah kunci menghadapi tugas mendadak."},
{id:"TKP-149", q:"Seorang rekan satu tim menyebarkan gosip negatif tentang Anda ke rekan lain. Tindakan terbaik adalah ....", opts:[{t:"Mengajaknya bicara empat mata untuk klarifikasi dan menyelesaikan masalah secara dewasa", s:5},{t:"Melaporkan ke atasan tanpa klarifikasi", s:4},{t:"Diam dan membiarkan nama baik rusak", s:3},{t:"Mengonfrontasi dengan emosi di depan umum", s:2},{t:"Menyebarkan gosip balasan yang lebih buruk", s:1}], ex:"Klarifikasi empat mata menyelesaikan gosip pada akarnya tanpa memperkeruh suasana."},
{id:"TKP-150", q:"Pembagian honor kegiatan tim tidak transparan dan Anda curiga ada yang tidak beres. Langkah terbaik adalah ....", opts:[{t:"Meminta keterbukaan rincian pembagian secara sopan dalam forum tim", s:5},{t:"Menolak honor tersebut sebagai protes", s:4},{t:"Diam saja asalkan Anda dapat bagian", s:3},{t:"Menyebarkan kecurigaan ke rekan lain", s:2},{t:"Menuduh bendahara di depan tim", s:1}], ex:"Meminta transparansi rincian lewat forum resmi adalah cara yang benar menuntut akuntabilitas."},
{id:"TKP-151", q:"Seorang warga menolak didatangi petugas perempuan ke rumahnya karena adat setempat. Padahal petugas yang ditugaskan adalah perempuan. Sikap terbaik adalah ....", opts:[{t:"Menghormati adat dengan mengatur ulang: petugas laki-laki yang berkunjung atau didampingi tokoh setempat", s:5},{t:"Memaksa warga menerima petugas perempuan demi kesetaraan", s:4},{t:"Membatalkan kunjungan dan menandai warga tidak kooperatif", s:3},{t:"Melaporkan warga sebagai diskriminatif", s:2},{t:"Mengirim petugas perempuan diam-diam", s:1}], ex:"Menghormati adat setempat dengan penyesuaian petugas adalah pelayanan yang peka budaya."},
{id:"TKP-152", q:"Upacara adat menutup jalan utama sehingga warga lain protes karena terhambat. Sebagai aparat kelurahan, Anda sebaiknya ....", opts:[{t:"Memfasilitasi musyawarah: pengaturan waktu, jalur alternatif, dan pemberitahuan sebelumnya agar adat dan kepentingan umum seimbang", s:5},{t:"Melarang upacara adat demi kelancaran lalu lintas", s:4},{t:"Membiarkan penutupan tanpa pengaturan", s:3},{t:"Memihak warga yang protes", s:2},{t:"Mengabaikan karena itu urusan adat", s:1}], ex:"Fasilitasi musyawarah menyeimbangkan pelestarian adat dan hak pengguna jalan."},
{id:"TKP-153", q:"Orang tua mengajukan dispensasi nikah untuk anaknya yang masih di bawah umur dengan alasan adat setempat. Sebagai petugas pencatatan, Anda harus ....", opts:[{t:"Menolak dengan penjelasan bahwa dispensasi hanya lewat penetapan pengadilan dan ada syarat ketat demi perlindungan anak", s:5},{t:"Menolak mentah-mentah tanpa penjelasan", s:4},{t:"Mengabulkan demi menghormati adat", s:3},{t:"Mengabulkan diam-diam", s:2},{t:"Meminta imbalan untuk mengurus", s:1}], ex:"Perlindungan anak adalah prioritas; dispensasi nikah hanya melalui mekanisme pengadilan yang ketat."},
{id:"TKP-154", q:"Dua saudara beda agama bersengketa atas tanah warisan orang tua dan meminta Anda sebagai lurah menjadi penengah. Tindakan terbaik adalah ....", opts:[{t:"Memfasilitasi mediasi secara netral berdasarkan dokumen kepemilikan dan hukum waris yang berlaku, tanpa memihak keyakinan", s:5},{t:"Membagi tanah sama rata tanpa melihat dokumen", s:4},{t:"Menolak terlibat karena sensitif", s:3},{t:"Memihak saudara yang seagama dengan Anda", s:2},{t:"Menyuruh mereka berkelahi saja", s:1}], ex:"Mediasi netral berbasis dokumen dan hukum menyelesaikan sengketa waris tanpa bias agama."},
{id:"TKP-155", q:"Seorang warga tunarungu membutuhkan layanan, tetapi tidak ada petugas yang menguasai bahasa isyarat. Tindakan paling tepat adalah ....", opts:[{t:"Menggunakan tulisan/gambar untuk berkomunikasi saat itu, dan mengusulkan pelatihan dasar bahasa isyarat bagi petugas", s:5},{t:"Meminta warga membawa penerjemah sendiri selalu", s:4},{t:"Menyuruh warga kembali lain waktu", s:3},{t:"Berkomunikasi dengan teriakan agar terbaca bibir", s:2},{t:"Mengabaikan dan melayani seadanya", s:1}], ex:"Solusi komunikasi alternatif saat itu plus usulan pelatihan adalah pelayanan inklusif yang berkelanjutan."},
{id:"TKP-156", q:"Kelompok pengajian rutin meminta memakai aula kantor untuk kegiatan mingguan. Sikap Anda sebagai pengelola adalah ....", opts:[{t:"Menolak dengan alasan fasilitas negara tidak untuk kegiatan keagamaan tertentu; tawarkan mekanisme peminjaman resmi yang berlaku umum", s:5},{t:"Melarang semua kegiatan keagamaan di kantor", s:4},{t:"Mengizinkan karena mayoritas pegawai ikut", s:3},{t:"Mengizinkan diam-diam", s:2},{t:"Mengizinkan dengan bayaran", s:1}], ex:"Fasilitas negara harus netral; mekanisme peminjaman resmi yang berlaku umum menjaga keadilan."},
{id:"TKP-157", q:"Tradisi sedekah bumi membutuhkan izin keramaian, tetapi panitia mengajukan mendadak dua hari sebelum acara. Keputusan Anda adalah ....", opts:[{t:"Memproses cepat sesuai prosedur dengan melengkapi persyaratan esensial dan berkoordinasi dengan keamanan", s:5},{t:"Menolak karena mepet", s:4},{t:"Memberi izin lisan tanpa dokumen", s:3},{t:"Membiarkan acara jalan tanpa izin", s:2},{t:"Meminta pungutan tambahan agar cepat", s:1}], ex:"Percepatan proses resmi dengan koordinasi keamanan mendukung tradisi tanpa melanggar prosedur."},
{id:"TKP-158", q:"Seorang warga pendatang mencalonkan diri jadi ketua RT, tetapi warga lokal menolak dengan alasan 'bukan orang sini'. Sebagai fasilitator, Anda ....", opts:[{t:"Menjelaskan aturan pemilihan yang berbasis domisili (bukan asal-usul) dan memfasilitasi pemilihan yang demokratis", s:5},{t:"Membatalkan pemilihan", s:4},{t:"Memaksa warga menerima calon pendatang", s:3},{t:"Mendukung penolakan warga lokal", s:2},{t:"Membiarkan konflik tanpa campur tangan", s:1}], ex:"Hak dipilih berbasis domisili resmi; fasilitasi demokratis mencegah diskriminasi terhadap pendatang."},
{id:"TKP-159", q:"Satpol PP menertibkan anak jalanan dan pemulung di kawasan Anda. Warga meminta pendekatan yang humanis. Sikap terbaik adalah ....", opts:[{t:"Mendukung penertiban yang humanis: pendataan, pembinaan, dan rujukan ke dinas sosial untuk pemberdayaan", s:5},{t:"Menolak penertiban sama sekali", s:4},{t:"Mendukung penertiban keras agar jera", s:3},{t:"Membiarkan mereka tetap di jalan", s:2},{t:"Mengusir mereka ke wilayah lain", s:1}], ex:"Penertiban humanis plus rujukan pemberdayaan menyelesaikan masalah sosial sampai akarnya."},
{id:"TKP-160", q:"Warga berbeda pendapat soal penamaan gang: sebagian ingin nama tokoh lokal, sebagian ingin nama pahlawan nasional. Peran Anda adalah ....", opts:[{t:"Memfasilitasi musyawarah warga dengan mekanisme voting yang disepakati", s:5},{t:"Menunda tanpa batas waktu", s:4},{t:"Memilih nama pahlawan nasional karena lebih aman", s:3},{t:"Membiarkan mereka bertengkar", s:2},{t:"Memutuskan sendiri nama yang Anda suka", s:1}], ex:"Musyawarah dengan voting yang disepakati memberi legitimasi pada keputusan bersama."},
{id:"TKP-161", q:"Warga meminta dispensasi hajatan melebihi jam malam selama tujuh hari berturut-turut karena adat. Warga sekitar keberatan. Keputusan Anda adalah ....", opts:[{t:"Memfasilitasi kompromi: batasi jam dan tingkat kebisingan, beri tahu warga sekitar sebelumnya", s:5},{t:"Melarang total demi ketertiban", s:4},{t:"Mengizinkan penuh demi adat", s:3},{t:"Membiarkan tanpa izin", s:2},{t:"Meminta bayaran untuk izin", s:1}], ex:"Kompromi yang mengatur jam dan kebisingan menghormati adat sekaligus hak istirahat tetangga."},
{id:"TKP-162", q:"Acara adat dan acara dinas dijadwalkan di balai desa pada hari yang sama dan panitia saling klaim. Tindakan Anda adalah ....", opts:[{t:"Mempertemukan kedua panitia untuk mengatur ulang jadwal atau berbagi ruang/waktu secara adil", s:5},{t:"Menyerahkan ke siapa yang datang duluan", s:4},{t:"Memenangkan acara dinas karena lebih penting", s:3},{t:"Membiarkan kedua acara bertabrakan", s:2},{t:"Membatalkan acara adat", s:1}], ex:"Mediasi penjadwalan ulang yang adil menyelesaikan konflik pemakaian fasilitas umum."},
{id:"TKP-163", q:"Sebagian warga lebih percaya dukun beranak daripada puskesmas untuk persalinan, padahal risikonya tinggi. Sebagai petugas kesehatan, pendekatan terbaik adalah ....", opts:[{t:"Merangkul dukun beranak sebagai mitra: latih jadi pendamping rujukan ke puskesmas, bukan pesaing", s:5},{t:"Membiarkan karena itu pilihan warga", s:4},{t:"Melarang dukun beranak beroperasi", s:3},{t:"Mengabaikan masalah ini", s:2},{t:"Menakut-nakuti warga dengan risiko", s:1}], ex:"Kemitraan dengan dukun beranak sebagai perujuk menggabungkan kearifan lokal dan keselamatan medis."},
{id:"TKP-164", q:"Warga transmigran dan warga lokal bersengketa atas lahan garapan di perbatasan desa. Anda diminta memediasi. Tindakan terbaik adalah ....", opts:[{t:"Memverifikasi dokumen kepemilikan/garap kedua pihak dan memfasilitasi kesepakatan berbasis data", s:5},{t:"Membagi lahan sama rata tanpa verifikasi", s:4},{t:"Memihak warga lokal sebagai penduduk asli", s:3},{t:"Memihak transmigran karena program pemerintah", s:2},{t:"Menyerahkan ke preman setempat", s:1}], ex:"Mediasi berbasis verifikasi dokumen mencegah keberpihakan dan memberi dasar penyelesaian yang adil."},
{id:"TKP-165", q:"Karang taruna dan sebuah ormas bersitegang soal pengelolaan parkir liar di kawasan pasar. Potensi bentrok ada. Sikap Anda adalah ....", opts:[{t:"Mengajak kedua pihak berdialog, menegaskan parkir liar melanggar aturan, dan mengusulkan pengelolaan resmi yang melibatkan keduanya", s:5},{t:"Menutup area parkir total", s:4},{t:"Melaporkan keduanya ke polisi tanpa dialog", s:3},{t:"Membiarkan mereka berebut", s:2},{t:"Memihak ormas yang lebih kuat", s:1}], ex:"Dialog yang menegaskan aturan plus usulan pengelolaan resmi mengubah konflik menjadi kerja sama."},
{id:"TKP-166", q:"Komputer dinas Anda terkunci ransomware dengan pesan permintaan tebusan. Tindakan pertama yang paling tepat adalah ....", opts:[{t:"Segera memutus jaringan, tidak membayar, dan melaporkan ke tim IT/keamanan siber sesuai prosedur insiden", s:5},{t:"Me-restart komputer berulang kali", s:4},{t:"Mencoba membuka kunci sendiri dengan tutorial internet", s:3},{t:"Menyembunyikan kejadian agar tidak dimarahi", s:2},{t:"Membayar tebusan agar data kembali", s:1}], ex:"Isolasi jaringan dan pelaporan resmi adalah respons insiden siber yang benar; membayar tebusan tidak menjamin data kembali."},
{id:"TKP-167", q:"Beredar kabar data warga bocor dan diduga berasal dari akun sistem Anda. Tindakan paling tepat adalah ....", opts:[{t:"Segera melaporkan ke atasan dan tim IT, mengganti kredensial, dan kooperatif dalam investigasi", s:5},{t:"Diam menunggu masalah reda", s:4},{t:"Menyebarkan kabar tandingan", s:3},{t:"Menyangkal dan menyalahkan rekan", s:2},{t:"Menghapus akun Anda untuk menghilangkan jejak", s:1}], ex:"Pelaporan cepat, pengamanan akun, dan kooperatif dalam investigasi adalah tanggung jawab pemilik akun."},
{id:"TKP-168", q:"Seorang rekan mengunggah foto kegiatan kantor ke media sosial, tetapi fotonya memperlihatkan dokumen berisi data warga. Sikap Anda adalah ....", opts:[{t:"Mengingatkan rekan untuk menghapus/menyensor foto itu dan menjelaskan risiko kebocoran data pribadi", s:5},{t:"Melaporkan rekan ke polisi seketika", s:4},{t:"Mengabaikan karena sudah terlanjur", s:3},{t:"Mengomentari foto itu dengan candaan", s:2},{t:"Ikut membagikan foto itu", s:1}], ex:"Teguran cepat plus edukasi mencegah kebocoran data pribadi warga yang lebih luas."},
{id:"TKP-169", q:"Rekaman video rapat internal yang bersifat rahasia bocor ke publik. Anda dicurigai sebagai sumbernya. Tindakan terbaik adalah ....", opts:[{t:"Bersikap kooperatif dalam penelusuran, menjelaskan fakta yang Anda ketahui, dan tidak menyebarkan ulang", s:5},{t:"Membuat pernyataan pers sendiri", s:4},{t:"Menghapus semua aplikasi chat Anda", s:3},{t:"Menuduh balik rekan lain", s:2},{t:"Kabur dan tidak masuk kerja", s:1}], ex:"Kooperatif dan jujur dalam penelusuran adalah sikap benar bagi yang tidak bersalah."},
{id:"TKP-170", q:"Atasan meminta Anda membuka blokir situs yang diblokir kantor dengan alasan 'keperluan dinas' yang tidak jelas. Sikap Anda adalah ....", opts:[{t:"Meminta penjelasan tertulis keperluan dinasnya dan mengikuti prosedur pengajuan pembukaan blokir resmi", s:5},{t:"Menolak mentah-mentah tanpa penjelasan", s:4},{t:"Membuka blokir demi perintah atasan", s:3},{t:"Memberi tahu seluruh kantor", s:2},{t:"Membuka blokir diam-diam", s:1}], ex:"Permintaan tertulis dan prosedur resmi melindungi Anda bila situs itu disalahgunakan."},
{id:"TKP-171", q:"Seorang rekan meminta Anda mencatatkan kehadirannya di e-absensi (titip fingerprint) karena ia terlambat. Respons Anda adalah ....", opts:[{t:"Menolak dan menjelaskan bahwa titip absen adalah pemalsuan data kehadiran", s:5},{t:"Membantu tetapi melaporkannya", s:4},{t:"Mengabaikan permintaannya tanpa jawaban", s:3},{t:"Membantu karena hanya sekali", s:2},{t:"Membantu dengan syarat ia membantu Anda lain waktu", s:1}], ex:"Titip absen adalah pemalsuan dokumen kehadiran; menolak dengan penjelasan adalah integritas."},
{id:"TKP-172", q:"Grup WhatsApp dinas mulai dipakai untuk kampanye politik dan jualan online oleh oknum pegawai. Sebagai anggota, Anda sebaiknya ....", opts:[{t:"Mengingatkan bahwa grup dinas hanya untuk keperluan kedinasan sesuai aturan, dan melaporkan bila berlanjut", s:5},{t:"Keluar dari grup diam-diam", s:4},{t:"Membiarkan karena takut dimusuhi", s:3},{t:"Ikut berjualan juga", s:2},{t:"Menyebarkan kampanye tandingan", s:1}], ex:"Menegakkan peruntukan grup dinas menjaga netralitas ASN dan profesionalitas komunikasi."},
{id:"TKP-173", q:"Setelah pembaruan sistem, sebagian data arsip digital hilang dan ternyata tidak ada cadangan (backup). Tindakan Anda adalah ....", opts:[{t:"Melaporkan segera, mengupayakan pemulihan data, dan mengusulkan kebijakan backup rutin", s:5},{t:"Membuat ulang data dari ingatan", s:4},{t:"Menyalahkan vendor pembaruan", s:3},{t:"Menyembunyikan kejadian dari atasan", s:2},{t:"Berpura-pura data tidak penting", s:1}], ex:"Pelaporan cepat, upaya pemulihan, dan kebijakan backup mencegah terulangnya kehilangan data."},
{id:"TKP-174", q:"Seorang warga mengirim foto KTP dan data pribadinya ke nomor WhatsApp pribadi Anda untuk pengurusan. Tindakan paling tepat adalah ....", opts:[{t:"Mengarahkannya ke kanal resmi, menghapus data dari ponsel pribadi setelah dipindahkan, dan menjelaskan risiko keamanan", s:5},{t:"Memproses dari WhatsApp pribadi demi cepat", s:4},{t:"Mengabaikan pesan warga", s:3},{t:"Menyimpan data itu di galeri ponsel", s:2},{t:"Meneruskan data itu ke grup kantor", s:1}], ex:"Data pribadi warga wajib lewat kanal resmi; menghapus dari perangkat pribadi mencegah kebocoran."},
{id:"TKP-175", q:"Beredar foto pimpinan yang diedit (deepfake) disertai narasi hoaks yang merugikan instansi. Anda diminta membantu menangkalnya. Langkah terbaik adalah ....", opts:[{t:"Membantu klarifikasi resmi dengan fakta, melaporkan konten ke platform, dan mengedukasi tentang bahaya deepfake", s:5},{t:"Menyebarkan foto asli pimpinan tanpa konteks", s:4},{t:"Mengabaikan karena bukan urusan Anda", s:3},{t:"Menuduh pembuatnya tanpa bukti", s:2},{t:"Membalas dengan hoaks tandingan", s:1}], ex:"Klarifikasi berbasis fakta plus pelaporan konten adalah respons profesional terhadap disinformasi."},
{id:"TKP-176", q:"Spanduk dan simbol ormas terlarang terpasang di wilayah kerja Anda. Tindakan paling tepat adalah ....", opts:[{t:"Melaporkan ke atasan dan berkoordinasi dengan aparat (polisi/kesbangpol) untuk penertiban resmi", s:5},{t:"Mengganti dengan spanduk lain", s:4},{t:"Memfoto dan memviralkan", s:3},{t:"Menurunkan sendiri secara diam-diam malam hari", s:2},{t:"Membiarkan karena takut berkonflik", s:1}], ex:"Simbol ormas terlarang ditangani lewat koordinasi resmi dengan aparat, bukan aksi sepihak."},
{id:"TKP-177", q:"Seorang rekan menolak ikut upacara bendera dan hormat bendera dengan alasan ideologi pribadinya. Sikap Anda adalah ....", opts:[{t:"Mengingatkannya bahwa sebagai ASN ia terikat sumpah dan aturan disiplin, serta melaporkannya bila berlanjut", s:5},{t:"Membiarkan karena itu hak pribadi", s:4},{t:"Memaksanya ikut dengan ancaman", s:3},{t:"Mengejeknya di depan rekan lain", s:2},{t:"Ikut menolak sebagai solidaritas", s:1}], ex:"ASN terikat sumpah dan disiplin; penolakan simbol negara wajib diingatkan dan dilaporkan."},
{id:"TKP-178", q:"Anda mendapati anak buah mulai terpapar paham khilafah dari konten media sosial dan menyebarkannya di lingkungan kerja. Tindakan terbaik adalah ....", opts:[{t:"Melakukan pembinaan: dialog, penguatan wawasan kebangsaan, dan bila berlanjut laporkan ke atasan/pembina", s:5},{t:"Melaporkan ke polisi tanpa pembinaan dulu", s:4},{t:"Langsung memecatnya", s:3},{t:"Membiarkan karena masih sebatas wacana", s:2},{t:"Menyebarkan aibnya ke seluruh kantor", s:1}], ex:"Pembinaan dan penguatan wawasan kebangsaan dulu; pelaporan menyusul bila tidak berubah."},
{id:"TKP-179", q:"Ada penggalangan donasi di lingkungan kantor yang ternyata disalurkan ke kelompok terlarang. Anda sudah sempat berdonasi. Tindakan Anda adalah ....", opts:[{t:"Melaporkan temuan itu ke atasan/aparat, menghentikan partisipasi, dan mengingatkan rekan lain", s:5},{t:"Meminta kembali donasi Anda", s:4},{t:"Menyebarkan ke media sosial", s:3},{t:"Menarik donasi mustahil; biarkan saja", s:2},{t:"Diam saja karena sudah terlanjur", s:1}], ex:"Melaporkan aliran dana ke kelompok terlarang adalah kewajiban; mengingatkan rekan mencegah korban lebih banyak."},
{id:"TKP-180", q:"Seorang penceramah di masjid kantor menyampaikan ceramah yang mengkafirkan pemerintah yang sah. Sebagai pengurus masjid, Anda sebaiknya ....", opts:[{t:"Menegur dan menghentikan materi yang memecah belah, serta memastikan penceramah berikutnya sesuai ketentuan", s:5},{t:"Mengusir penceramah dengan kasar di tengah ceramah", s:4},{t:"Merekam dan memviralkan ceramahnya", s:3},{t:"Membiarkan karena kebebasan berpendapat", s:2},{t:"Menutup masjid kantor", s:1}], ex:"Masjid kantor tidak boleh jadi mimbar provokasi; tegur dan pastikan materi sesuai ketentuan."}
];
